const attrs = $json.body.object_attributes;
const branch = attrs.source_branch || '';
const m = branch.match(/^task\/GL-(\d+)$/);
return [{ json: { mr_iid: attrs.iid, task_iid: m ? m[1] : null, source_branch: branch, flow_id: $json.body.flow_id ?? '', retry_count: $json.body.retry_count ?? 0 } }];

// ponytail: agent sometimes narrates ("Comment posted successfully...")
// before the verdict instead of leading with it despite the prompt asking
// for verdict-first -- scan every line for an exact verdict token instead
// of trusting output.startsWith().
const out = ($json.output || '').trim();
const lines = out.split('\n').map(l => l.trim());
let tl_result = 'UNKNOWN';
if (!$json.succeeded) tl_result = 'JOB_FAILED';
else if (lines.includes('REQUEST_CHANGES')) tl_result = 'REQUEST_CHANGES';
else if (lines.includes('APPROVE')) tl_result = 'APPROVE';
return [{ json: { tl_result, tl_notes: out || '(tech-lead review job produced no output — check the Job logs in the sdlc namespace)' } }];

// ponytail: GitLab's pipeline webhook never gets routed back to this
// execution's dynamic wait-resume URL (nothing in F-00/F-09 does that) --
// a resume:webhook Wait node here would just hang forever. Poll instead,
// same deadline+Wait+IF-loop shape F-31 already uses for Job status.
return [{ json: { deadline: Date.now() + 15 * 60 * 1000 } }];

const deadline = $node["Set CI Deadline"].json.deadline;
const mrIid = $node["Extract MR Info"].json.mr_iid;
const projectId = $node['Webhook Trigger'].json.body.project?.id ?? $env.GITLAB_PROJECT_ID;
const pipelines = await this.helpers.httpRequest({
  method: 'GET',
  url: `${$env.GITLAB_URL}/api/v4/projects/${projectId}/merge_requests/${mrIid}/pipelines`,
  headers: { 'PRIVATE-TOKEN': $env.GITLAB_TOKEN },
  json: true,
});
const latest = Array.isArray(pipelines) && pipelines.length ? pipelines[0] : null;
const rawStatus = latest ? latest.status : 'none';
const stillRunning = ['running', 'pending', 'created', 'waiting_for_resource', 'preparing'].includes(rawStatus);
const timedOut = Date.now() > deadline;
const done = !stillRunning || timedOut;
const status = (timedOut && stillRunning) ? 'timeout' : rawStatus;
return [{ json: { done, status, pipeline_url: latest?.web_url ?? '' } }];

const taigaAuth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const id = $node["Extract MR Info"].json.task_iid;
const task = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/tasks/${id}`, headers: taigaAuth, json: true });
const statusesRes = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/task-statuses?project=${$env.TAIGA_PROJECT_ID}`, headers: taigaAuth, json: true });
const status = statusesRes.find(s => s.name === 'Closed');
await this.helpers.httpRequest({ method: 'PATCH', url: `${$env.TAIGA_URL}/api/v1/tasks/${id}`, headers: { ...taigaAuth, 'Content-Type': 'application/json' }, body: { version: task.version, status: status.id }, json: true });
return [{ json: $json }];

// ponytail: retry_count was read from the inbound webhook body, but
// nothing anywhere ever sets/increments it -- every real GitLab webhook
// call is stateless and arrives with no such field, so the escalate
// branch below was permanently unreachable. Count actual "TL review:"
// comments already posted on the Taiga task instead (TL Review Input's
// own prompt always posts one with that exact prefix) -- self-contained,
// no external counter needed.
const taigaAuth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const taskId = $node["Extract MR Info"].json.task_iid;
const history = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/history/task/${taskId}`, headers: taigaAuth, json: true });
const attempt_count = (Array.isArray(history) ? history : []).filter(h => typeof h.comment === 'string' && h.comment.startsWith('TL review:')).length;
return [{ json: { ...$json, attempt_count } }];

// ponytail: TL's own review (and its Taiga comment) only covers code vs
// spec -- it never checks CI, so a CI-only failure needs its own comment
// or the developer only sees "TL review: APPROVE" and no clue why the MR
// is still blocked.
if ($json.status === 'success') return [{ json: $json }];
const taigaAuth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const id = $node["Extract MR Info"].json.task_iid;
const task = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/tasks/${id}`, headers: taigaAuth, json: true });
const comment = `CI pipeline ${$json.status}${$json.pipeline_url ? ' — ' + $json.pipeline_url : ''}. Fix the pipeline and push again; this MR cannot be merged until it's green.`;
await this.helpers.httpRequest({ method: 'PATCH', url: `${$env.TAIGA_URL}/api/v1/tasks/${id}`, headers: { ...taigaAuth, 'Content-Type': 'application/json' }, body: { version: task.version, comment }, json: true });
return [{ json: $json }];

const taigaAuth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const id = $node["Extract MR Info"].json.task_iid;
const mrIid = $node["Extract MR Info"].json.mr_iid;
const task = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/tasks/${id}`, headers: taigaAuth, json: true });
const comment = `⚠️ TL review failed 3 times on MR !${mrIid} — handing over to a human reviewer for manual review and merge decision. Last TL verdict: ${$json.tl_result}${$json.status !== 'success' ? ' — CI pipeline ' + $json.status : ''}.`;
await this.helpers.httpRequest({ method: 'PATCH', url: `${$env.TAIGA_URL}/api/v1/tasks/${id}`, headers: { ...taigaAuth, 'Content-Type': 'application/json' }, body: { version: task.version, comment }, json: true });
return [{ json: $json }];
